using System;
using System.Collections.Generic;
using System.Threading;
using System.Security.Cryptography;
using System.IO;

namespace ImagePipeline
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private CircuitState _state = CircuitState.Closed;
        private int _failureCount = 0;
        private readonly int _threshold = 3;
        private DateTime _lastFailure = DateTime.MinValue;
        private readonly TimeSpan _timeout = TimeSpan.FromSeconds(30);
        private readonly object _lock = new object();

        public bool AllowRequest()
        {
            lock (_lock)
            {
                if (_state == CircuitState.Closed) return true;
                if (_state == CircuitState.Open)
                {
                    if (DateTime.UtcNow - _lastFailure > _timeout)
                    {
                        _state = CircuitState.HalfOpen;
                        return true;
                    }
                    return false;
                }
                return true; // HalfOpen allows one request
            }
        }

        public void RecordSuccess()
        {
            lock (_lock) { _state = CircuitState.Closed; _failureCount = 0; }
        }

        public void RecordFailure()
        {
            lock (_lock)
            {
                _failureCount++;
                _lastFailure = DateTime.UtcNow;
                if (_failureCount >= _threshold) _state = CircuitState.Open;
            }
        }
    }

    public class ResourcePool
    {
        private readonly Dictionary<string, long> _allocations = new Dictionary<string, long>();
        private long _totalCapacity = 1073741824; // 1GB
        private long _available;
        private readonly object _poolLock = new object();

        public ResourcePool() { _available = _totalCapacity; }

        public string Borrow(long amount)
        {
            lock (_poolLock)
            {
                if (amount > _available) return null;
                _available -= amount;
                string token = GenerateToken();
                _allocations[token] = amount;
                return token;
            }
        }

        public bool Return(string token)
        {
            lock (_poolLock)
            {
                if (!_allocations.ContainsKey(token)) return false;
                _available += _allocations[token];
                _allocations.Remove(token);
                return true;
            }
        }

        public long GetBorrowed(string token)
        {
            lock (_poolLock)
            {
                return _allocations.ContainsKey(token) ? _allocations[token] : 0;
            }
        }

        public long Available => _available;

        private string GenerateToken()
        {
            byte[] bytes = new byte[16];
            using (var rng = RandomNumberGenerator.Create()) { rng.GetBytes(bytes); }
            return Convert.ToBase64String(bytes);
        }
    }

    public class ImageProcessingJob
    {
        public string JobId { get; set; }
        public byte[] ImageData { get; set; }
        public string OutputPath { get; set; }
        public int Width { get; set; }
        public int Height { get; set; }
