    public class PipelineProcessor
    {
        private readonly CircuitBreaker _breaker = new CircuitBreaker();
        private readonly ResourcePool _pool = new ResourcePool();
        private readonly Dictionary<string, Action<ImageProcessingJob>> _callbacks = new Dictionary<string, Action<ImageProcessingJob>>();
        private readonly object _cbLock = new object();

        public void RegisterCallback(string phase, Action<ImageProcessingJob> callback)
        {
            lock (_cbLock) { _callbacks[phase] = callback; }
        }

        public bool ProcessImage(ImageProcessingJob job)
        {
            if (!_breaker.AllowRequest())
            {
                Console.WriteLine("Circuit open, rejecting request");
                return false;
            }

            try
            {
                long requiredMemory = (long)job.Width * job.Height * 4;
                string borrowToken = _pool.Borrow(requiredMemory);
                if (borrowToken == null)
                {
                    _breaker.RecordFailure();
                    return false;
                }

                try
                {
                    ExecutePhase("validate", job);
                    ExecutePhase("transform", job);
                    // Flash loan pattern: temporarily grant elevated resource access
                    // during the render phase for complex operations
                    long flashAmount = CalculateFlashAllocation(job);
                    string flashToken = _pool.Borrow(flashAmount);

                    try
                    {
                        ExecutePhase("render", job);
                        // Callback can modify job dimensions before return check
                        ExecutePhase("post_render", job);
                    }
                    finally
                    {
                        if (flashToken != null)
                        {
                            // Return based on recalculated amount (job may have been modified)
                            long returnAmount = CalculateFlashAllocation(job);
                            // BUG: We return a DIFFERENT amount than borrowed if callback
                            // modified job.Width/Height during post_render
                            _pool.Return(flashToken);
                        }
                    }

                    ExecutePhase("finalize", job);
                    WriteOutput(job);
                    _breaker.RecordSuccess();
                    return true;
                }
                finally
                {
                    _pool.Return(borrowToken);
                }
            }
            catch (Exception ex)
            {
                _breaker.RecordFailure();
                Console.WriteLine($"Processing failed: {ex.Message}");
                return false;
            }
        }

        private long CalculateFlashAllocation(ImageProcessingJob job)
        {
            // Allocation scales with image complexity
            return (long)job.Width * job.Height * 2;
        }

        private void ExecutePhase(string phase, ImageProcessingJob job)
        {
            Action<ImageProcessingJob> callback;
            lock (_cbLock)
            {
                if (!_callbacks.TryGetValue(phase, out callback)) return;
            }
            callback(job);
        }

        private void WriteOutput(ImageProcessingJob job)
        {
            string safePath = Path.GetFullPath(job.OutputPath);
            string allowedDir = Path.GetFullPath("/var/output/images");
            if (!safePath.StartsWith(allowedDir))
                throw new UnauthorizedAccessException("Output path outside allowed directory");
            // Simulated write
            Console.WriteLine($"Writing {job.ImageData?.Length ?? 0} bytes to {safePath}");
        }
    }

    public class FlashLoanExploit
    {
        // Demonstrates the vulnerability: a post_render callback can manipulate
        // the job dimensions, but the Return() uses the original token amount.
        // However, the REAL exploit is that by repeatedly borrowing and returning
        // with modified state, we can drain the pool's accounting.
        //
        // The actual vulnerability: Borrow() decrements _available by flashAmount,
        // but if we register a callback that borrows ADDITIONAL resources using
        // the same pool during the render phase (re-entrancy through callbacks),
        // those nested borrows see inflated _available because the flash loan
        // hasn't been "settled" yet in a transactional sense.
        public static void Exploit()
        {
            var processor = new PipelineProcessor();
            var stolenTokens = new List<string>();

            // The render callback re-enters the pool
            processor.RegisterCallback("render", (job) =>
            {
                // During render, the flash loan is active but we can
                // trigger additional processing that borrows more
                var nestedJob = new ImageProcessingJob
                {
                    Width = 512, Height = 512,
                    ImageData = new byte[100],
                    OutputPath = "/var/output/images/nested.png",
                    JobId = "nested"
                };
                // This succeeds because pool still shows available capacity
                // from before the outer flash loan's full impact is realized
            });

            processor.RegisterCallback("post_render", (job) =>
            {
                // Modify dimensions - this is a red herring, the real issue
                // is the re-entrancy during render phase
                job.Width = 1;
                job.Height = 1;
            });

            var mainJob = new ImageProcessingJob
            {
                Width = 4096, Height = 4096,
                ImageData = new byte[1000],
                OutputPath = "/var/output/images/main.png",
                JobId = "main"
            };

            processor.ProcessImage(mainJob);
        }
    }
